title=VALUES(title),icon=VALUES(icon),short_description=VALUES(short_description),description=VALUES(description),work_environment=VALUES(work_environment),skills=VALUES(skills),subjects=VALUES(subjects),education_path=VALUES(education_path),salary_range=VALUES(salary_range),outlook=VALUES(outlook),simulation_url=VALUES(simulation_url),simulation_label=VALUES(simulation_label),simulation_enabled=VALUES(simulation_enabled),riasec_weights=VALUES(riasec_weights),featured=VALUES(featured);
