INSERT INTO careers(title,slug,icon,short_description,description,work_environment,skills,subjects,education_path,salary_range,outlook,simulation_url,simulation_label,simulation_enabled,riasec_weights,featured) VALUES
('Lập trình viên','lap-trinh-vien','💻','Xây dựng phần mềm, website và ứng dụng giải quyết vấn đề thực tế.','Lập trình viên phân tích yêu cầu, viết mã, kiểm thử và cải tiến sản phẩm số. Nghề có nhiều nhánh như web, mobile, game, AI và hệ thống.','Công ty công nghệ; làm việc nhóm; có thể từ xa.','Tư duy logic, giải quyết vấn đề, tự học, giao tiếp','Toán, Tin học, Tiếng Anh','CNTT, Khoa học máy tính, Kỹ thuật phần mềm hoặc tự học có dự án','12–50+ triệu/tháng','Nhu cầu cao, thay đổi nhanh','https://scratch.mit.edu/','Trải nghiệm mô phỏng',1,JSON_OBJECT('R',60,'I',90,'A',55,'S',40,'E',45,'C',80),1),
('Kỹ sư trí tuệ nhân tạo','ky-su-tri-tue-nhan-tao','🤖','Phát triển hệ thống học từ dữ liệu để dự đoán và tự động hóa.','Kỹ sư AI xây dựng mô hình máy học, xử lý dữ liệu và đưa mô hình vào sản phẩm an toàn, hiệu quả.','Phòng nghiên cứu, công ty công nghệ, nhóm sản phẩm.','Toán, lập trình, phân tích dữ liệu, kiên trì','Toán, Tin học, Tiếng Anh','Khoa học máy tính, AI, Khoa học dữ liệu','18–70+ triệu/tháng','Tăng trưởng rất mạnh','https://quickdraw.withgoogle.com/','Trải nghiệm mô phỏng',1,JSON_OBJECT('R',50,'I',98,'A',55,'S',35,'E',45,'C',80),1),
('Bác sĩ','bac-si','🩺','Khám, chẩn đoán, điều trị và chăm sóc sức khỏe con người.','Bác sĩ vận dụng kiến thức y khoa, kỹ năng lâm sàng và sự thấu cảm để bảo vệ sức khỏe người bệnh.','Bệnh viện, phòng khám; áp lực và trách nhiệm cao.','Chuyên môn, quan sát, giao tiếp, bình tĩnh','Sinh học, Hóa học, Toán','Đại học Y và đào tạo chuyên khoa','15–60+ triệu/tháng','Nhu cầu ổn định lâu dài','https://www.cdc.gov/bam/body/index.html','Trải nghiệm mô phỏng',1,JSON_OBJECT('R',55,'I',92,'A',30,'S',90,'E',45,'C',75),1),
('Nhà thiết kế đồ họa','nha-thiet-ke-do-hoa','🎨','Truyền tải thông điệp bằng hình ảnh, chữ và bố cục.','Nhà thiết kế tạo nhận diện thương hiệu, ấn phẩm, giao diện và nội dung trực quan cho nhiều kênh.','Studio, agency, doanh nghiệp hoặc tự do.','Sáng tạo, thẩm mỹ, công cụ thiết kế, lắng nghe','Mỹ thuật, Tin học, Ngữ văn','Thiết kế đồ họa, Mỹ thuật đa phương tiện hoặc portfolio','8–35+ triệu/tháng','Nhiều cơ hội, cạnh tranh theo năng lực','https://www.canva.com/designschool/','Trải nghiệm mô phỏng',1,JSON_OBJECT('R',35,'I',40,'A',98,'S',45,'E',50,'C',55),1),
('Giáo viên','giao-vien','👩‍🏫','Giúp người học phát triển kiến thức, kỹ năng và nhân cách.','Giáo viên thiết kế bài học, tổ chức hoạt động, đánh giá và đồng hành với sự tiến bộ của học sinh.','Trường học, trung tâm, nền tảng trực tuyến.','Trình bày, thấu cảm, tổ chức, kiên nhẫn','Tùy môn chuyên ngành, Ngữ văn','Đại học Sư phạm hoặc chuyên ngành kèm nghiệp vụ','8–25+ triệu/tháng','Ổn định, chuyển đổi số mạnh','https://kahoot.com/','Trải nghiệm mô phỏng',1,JSON_OBJECT('R',25,'I',65,'A',55,'S',98,'E',55,'C',70),1),
('Chuyên viên Marketing','chuyen-vien-marketing','📣','Kết nối sản phẩm với khách hàng qua nội dung và chiến dịch.','Chuyên viên marketing nghiên cứu khách hàng, lên chiến lược, sáng tạo nội dung và đo lường hiệu quả.','Doanh nghiệp, agency; nhịp độ nhanh, phối hợp nhiều nhóm.','Sáng tạo, phân tích, giao tiếp, công nghệ số','Ngữ văn, Toán, Tiếng Anh','Marketing, Kinh doanh, Truyền thông','10–40+ triệu/tháng','Nhu cầu cao, thiên về dữ liệu','https://ads.google.com/home/resources/','Trải nghiệm mô phỏng',1,JSON_OBJECT('R',25,'I',55,'A',80,'S',65,'E',90,'C',60),1),
('Kiến trúc sư','kien-truc-su','🏛️','Thiết kế không gian sống đẹp, an toàn và bền vững.','Kiến trúc sư kết hợp nghệ thuật và kỹ thuật để phát triển ý tưởng, bản vẽ và phối hợp thi công công trình.','Văn phòng thiết kế và công trường.','Không gian, thẩm mỹ, kỹ thuật, giao tiếp','Toán, Vật lý, Mỹ thuật','Kiến trúc; thường có môn năng khiếu','12–45+ triệu/tháng','Gắn với đô thị hóa xanh','https://floorplanner.com/','Trải nghiệm mô phỏng',1,JSON_OBJECT('R',70,'I',65,'A',95,'S',40,'E',55,'C',65),0),
('Kỹ sư cơ khí','ky-su-co-khi','⚙️','Thiết kế, chế tạo và vận hành máy móc, hệ thống cơ khí.','Kỹ sư cơ khí dùng nguyên lý vật lý và công nghệ để tạo, tối ưu sản phẩm và dây chuyền.','Nhà máy, phòng thiết kế, phòng thí nghiệm.','Kỹ thuật, CAD, giải quyết vấn đề, an toàn','Toán, Vật lý, Công nghệ','Kỹ thuật cơ khí, Cơ điện tử','10–40+ triệu/tháng','Ổn định, tự động hóa tăng','https://www.tinkercad.com/','Trải nghiệm mô phỏng',1,JSON_OBJECT('R',98,'I',78,'A',40,'S',30,'E',45,'C',75),0),
('Chuyên viên tâm lý','chuyen-vien-tam-ly','🧠','Lắng nghe và hỗ trợ sức khỏe tinh thần, hành vi con người.','Chuyên viên tâm lý đánh giá, tham vấn và xây dựng kế hoạch hỗ trợ dựa trên bằng chứng và đạo đức nghề nghiệp.','Trường học, bệnh viện, trung tâm tham vấn.','Lắng nghe, thấu cảm, phân tích, bảo mật','Sinh học, Ngữ văn, GDCD','Tâm lý học và đào tạo thực hành chuyên sâu','9–35+ triệu/tháng','Nhu cầu xã hội ngày càng tăng','https://www.16personalities.com/free-personality-test','Trải nghiệm mô phỏng',1,JSON_OBJECT('R',20,'I',75,'A',45,'S',98,'E',35,'C',55),0),
('Luật sư','luat-su','⚖️','Tư vấn, bảo vệ quyền và lợi ích hợp pháp cho cá nhân, tổ chức.','Luật sư nghiên cứu hồ sơ, tư vấn pháp lý, đàm phán và tham gia tố tụng với chuẩn mực nghề nghiệp cao.','Văn phòng luật, doanh nghiệp, tòa án.','Lập luận, đọc hiểu, thuyết phục, đạo đức','Ngữ văn, Lịch sử, Tiếng Anh','Cử nhân Luật và đào tạo hành nghề','12–60+ triệu/tháng','Ổn định, chuyên môn hóa cao','https://www.icivics.org/games','Trải nghiệm mô phỏng',1,JSON_OBJECT('R',20,'I',78,'A',45,'S',65,'E',90,'C',78),0),
('Nhà báo / Biên tập viên','nha-bao-bien-tap-vien','📰','Tìm hiểu, kiểm chứng và kể những câu chuyện có ích cho công chúng.','Nhà báo thu thập thông tin, phỏng vấn, xác minh và sản xuất nội dung trên báo chí đa nền tảng.','Tòa soạn, hiện trường; thời hạn nhanh.','Viết, tò mò, kiểm chứng, giao tiếp','Ngữ văn, Lịch sử, Ngoại ngữ','Báo chí, Truyền thông hoặc chuyên ngành liên quan','8–30+ triệu/tháng','Chuyển mạnh sang đa phương tiện','https://www.canva.com/create/newsletters/','Trải nghiệm mô phỏng',1,JSON_OBJECT('R',25,'I',70,'A',88,'S',72,'E',55,'C',60),0),
('Chuyên viên tài chính','chuyen-vien-tai-chinh','📊','Phân tích số liệu để hỗ trợ quyết định tiền tệ và đầu tư.','Chuyên viên tài chính lập kế hoạch, phân tích hiệu quả, quản trị rủi ro và trình bày khuyến nghị.','Ngân hàng, doanh nghiệp, công ty chứng khoán.','Phân tích, bảng tính, cẩn trọng, trình bày','Toán, Tin học, Tiếng Anh','Tài chính, Ngân hàng, Kế toán, Kinh tế','12–50+ triệu/tháng','Ổn định, công nghệ tài chính tăng','https://playspent.org/','Trải nghiệm mô phỏng',1,JSON_OBJECT('R',20,'I',78,'A',25,'S',40,'E',75,'C',98),0),
('Quản trị nhân sự','quan-tri-nhan-su','🤝','Thu hút, phát triển và gắn kết con người trong tổ chức.','Chuyên viên nhân sự tuyển dụng, đào tạo, xây dựng chính sách và văn hóa làm việc tích cực.','Mọi loại hình doanh nghiệp, giao tiếp thường xuyên.','Giao tiếp, tổ chức, công bằng, phân tích','Ngữ văn, Toán, Tiếng Anh','Quản trị nhân lực, Kinh doanh, Luật','9–35+ triệu/tháng','Ổn định, tập trung trải nghiệm nhân viên','https://www.mindtools.com/a5ykiuq/team-building-exercises-and-activities','Trải nghiệm mô phỏng',1,JSON_OBJECT('R',15,'I',45,'A',40,'S',88,'E',82,'C',75),0),
('Kỹ sư môi trường','ky-su-moi-truong','🌱','Giải quyết vấn đề nước, chất thải và phát triển bền vững.','Kỹ sư môi trường khảo sát, thiết kế giải pháp xử lý, giám sát chỉ số và tuân thủ quy định môi trường.','Phòng thí nghiệm, doanh nghiệp, hiện trường.','Khoa học, kỹ thuật, dữ liệu, trách nhiệm','Hóa học, Sinh học, Toán','Kỹ thuật môi trường, Quản lý tài nguyên','10–35+ triệu/tháng','Tăng cùng nhu cầu phát triển xanh','https://climatekids.nasa.gov/menu/play/','Trải nghiệm mô phỏng',1,JSON_OBJECT('R',75,'I',90,'A',30,'S',60,'E',35,'C',70),0),
('Đầu bếp','dau-bep','👨‍🍳','Sáng tạo món ăn và vận hành trải nghiệm ẩm thực an toàn.','Đầu bếp chuẩn bị nguyên liệu, chế biến, trình bày món ăn và phối hợp đội bếp trong môi trường tốc độ cao.','Nhà hàng, khách sạn, bếp sản xuất.','Vị giác, khéo léo, kỷ luật, làm việc nhóm','Công nghệ, Hóa học, Sinh học','Trường nghề ẩm thực hoặc học việc thực tế','8–35+ triệu/tháng','Nhu cầu rộng, cơ hội kinh doanh','https://pbskids.org/games/cooking/','Trải nghiệm mô phỏng',1,JSON_OBJECT('R',85,'I',35,'A',82,'S',50,'E',55,'C',72),0)
